export function validateSignup(body: unknown): SignupResult {
  const input: Record<string, unknown> =
    typeof body === 'object' && body !== null ? (body as Record<string, unknown>) : {}
  const errors: FieldErrors = {}

  const parsed = signupSchema.safeParse(input)
  if (!parsed.success) {
    for (const issue of parsed.error.issues) {
      const path = issue.path.join('.')
      ;(errors[path] ??= []).push(issue.message)
    }
  }

  // Only compare when a password was given; a missing password is already reported.
  const password = blankAsMissing(input.password)
  const confirmPassword = blankAsMissing(input.confirmPassword)
  if (typeof password === 'string' && confirmPassword !== password) {
    ;(errors.confirmPassword ??= []).push('Passwords do not match')
  }

  if (Object.keys(errors).length > 0 || !parsed.success) return { ok: false, errors }

  const { confirmPassword: _confirmPassword, ...user } = parsed.data
  return { ok: true, user }
}

